import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { mkdir, mkdtemp, readFile, rm } from "node:fs/promises";
import { resolve } from "node:path";
import { after, test } from "node:test";
import { pathToFileURL } from "node:url";

import { build } from "rolldown";

// src/Batcave/ is generated by `npm run sync:comics`; without it there is
// nothing to test yet.
const synced = existsSync("src/Batcave/main.ts");
const BASE = "https://batcave.biz";
// Pages captured on 27 October 2026 from the live site (raw server HTML).
const fixture = (name) => readFile(`fixtures/batcave/${name}`);

const requests = [];
let source;
if (synced) {
  await mkdir("node_modules/.cache", { recursive: true });
  const directory = await mkdtemp(resolve("node_modules/.cache/tascabile-batcave-"));
  after(() => rm(directory, { recursive: true, force: true }));
  await build({
    input: { batcave: "src/Batcave/main.ts" },
    external: ["@paperback/types", "cheerio", "htmlparser2"],
    output: { dir: directory, format: "esm", entryFileNames: "[name].mjs" },
  });

  const routes = {
    [`GET ${BASE}`]: async () => Buffer.from("<html></html>"),
    [`GET ${BASE}/page/1`]: () => fixture("home-2026-10.html"),
    [`GET ${BASE}/search/batman`]: () => fixture("search-batman-2026-10.html"),
    [`POST ${BASE}/comix/`]: () => fixture("top-rated-2026-10.html"),
    [`GET ${BASE}/33758-batman-2025.html`]: () => fixture("detail-batman-2025-2026-10.html"),
    [`POST ${BASE}/engine/ajax/controller.php?mod=api&action=reader/getChapterData`]: () =>
      fixture("chapter-data-2026-10.json"),
  };
  const state = new Map();
  globalThis.Application = {
    getState: (key) => state.get(key),
    setState: (value, key) => state.set(key, value),
    getDefaultUserAgent: async () => "test",
    arrayBufferToUTF8String: (data) => Buffer.from(data).toString("utf8"),
    Selector: (target, method) => ({ target, method }),
    async scheduleRequest(request) {
      requests.push(request);
      const route = routes[`${request.method} ${request.url}`];
      if (!route) return [{ status: 404, headers: {}, url: request.url }, new ArrayBuffer(0)];
      const body = await route();
      const data = body.buffer.slice(body.byteOffset, body.byteOffset + body.byteLength);
      return [{ status: 200, headers: { "content-type": "text/html" }, url: request.url }, data];
    },
  };
  ({ Batcave: source } = await import(pathToFileURL(`${directory}/batcave.mjs`).href));
}

const batcaveTest = (name, fn) => test(name, { skip: !synced && "run npm run sync:comics" }, fn);

await batcaveTest("Latest Updates reads the front page cards", async () => {
  const { items, metadata } = await source.getDiscoverSectionItems({ id: "latest" }, undefined);
  assert.equal(items.length, 24);
  assert.deepEqual(
    { id: items[0].mangaId, title: items[0].title },
    {
      id: "38936-star-wars-the-mandalorian-and-grogu-nightmare-on-nevarro-2026.html",
      // The trailing "hot" icon <span> is not part of the title.
      title: "Star Wars: The Mandalorian and Grogu – Nightmare on Nevarro (2026-)",
    },
  );
  assert.ok(items.every((item) => item.imageUrl.startsWith("https://images.weserv.nl/?url=")));
  assert.deepEqual(metadata, { page: 2 });
});

await batcaveTest("Top Rated banners carry synopsis, publisher and year", async () => {
  const { items, metadata } = await source.getDiscoverSectionItems({ id: "top_rated" }, undefined);
  assert.equal(items.length, 10);
  const [first] = items;
  assert.equal(first.type, "featuredCarouselItem");
  assert.equal(first.title, "Harley Quinn Fartacular: Silent Butt Deadly (2025-)");
  assert.ok(first.summary.length > 20);
  assert.deepEqual(
    first.infoItems.map((item) => item.text),
    ["DC Comics", "2025"],
  );
  assert.match(requests.at(-1).body, /dlenewssortby=rating&dledirection=desc/u);
  assert.deepEqual(metadata, { page: 2 });
});

await batcaveTest("text search lists series with absolute covers", async () => {
  const { items, metadata } = await source.getSearchResults({ title: "batman" }, undefined);
  assert.equal(items.length, 10);
  assert.deepEqual(
    { id: items[0].mangaId, title: items[0].title },
    { id: "33758-batman-2025.html", title: "Batman (2025-)" },
  );
  assert.ok(items.every((item) => item.imageUrl.startsWith(`${BASE}/uploads/`)));
  assert.deepEqual(metadata, { page: 2 });
});

await batcaveTest("details read linked Writer/Artist rows and only real genres", async () => {
  const { mangaInfo } = await source.getMangaDetails("33758-batman-2025.html");
  assert.equal(mangaInfo.primaryTitle, "Batman (2025-)");
  assert.equal(mangaInfo.author, "Matt Fraction");
  assert.equal(mangaInfo.artist, "Jorge Jiménez");
  assert.equal(mangaInfo.status, "Ongoing");
  assert.equal(mangaInfo.thumbnailUrl, `${BASE}/uploads/posts/hd/33758.webp`);
  assert.match(mangaInfo.synopsis, /^A new dawn breaks over Gotham City/u);
  // User folders from "In collections" ("All of DC 1535") are not genres.
  assert.deepEqual(
    mangaInfo.tagGroups[0].tags.map((tag) => tag.title),
    ["action", "adventure", "crime", "fighting", "martial arts", "superhero", "Comic"],
  );
});

await batcaveTest("chapters come from window.__DATA__ with issue numbers and dates", async () => {
  const sourceManga = { mangaId: "33758-batman-2025.html" };
  const chapters = await source.getChapters(sourceManga);
  assert.equal(chapters.length, 14);
  const [latest] = chapters;
  assert.deepEqual(
    { id: latest.chapterId, num: latest.chapNum, title: latest.title },
    { id: "reader/33758/276264", num: 14, title: "Batman (2025-) #14" },
  );
  assert.deepEqual(
    [latest.publishDate.getFullYear(), latest.publishDate.getMonth(), latest.publishDate.getDate()],
    [2026, 9, 7],
  );
  assert.equal(chapters.at(-1).chapNum, 1);
});

await batcaveTest("chapter pages come from the reader API in order", async () => {
  const details = await source.getChapterDetails({
    chapterId: "reader/33758/276264",
    sourceManga: { mangaId: "33758-batman-2025.html" },
  });
  assert.deepEqual(JSON.parse(requests.at(-1).body), { news_id: "33758", chapter_id: "276264" });
  assert.equal(details.pages.length, 37);
  assert.ok(
    details.pages.every((url) => url.startsWith("https://img.batcave.biz/img/34/33758/276264/")),
  );
  assert.deepEqual(
    details.pages.slice(0, 3).map((url) => url.match(/\/(\d+)-[0-9a-f]+\.jpg/u)[1]),
    ["1", "2", "3"],
  );
});
